-- Payroll statutory review M7 (26 Nov 2026, founder answer 2730): the yearly cap on the employer's retirement contributions.
-- Income-tax Act 1961 s.17(2)(vii) (from TY 2020-21), carried into the 2025 Act: employer PF + NPS + superannuation above
-- Rs 7.5 lakh a year is a taxable perquisite. verify (CA). The accretion on the excess (s.17(2)(viia)) is not worked out.
INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.RETIRE-CAP', 'IN', '2020-v1', '2020-04-01', NULL, '{"kind":"retire_cap","cap":"750000"}', 'Income-tax Act 1961 s.17(2)(vii) (from TY 2020-21): employer PF, NPS (s.80CCD) and approved superannuation above Rs 7.5 lakh a year in total is a taxable perquisite; carried into the Income-tax Act 2025. verify (payroll statutory review M7).', true, 'published', 'IT-1961', CURRENT_TIMESTAMP)
ON CONFLICT DO NOTHING;
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'Employer 9,00,000: 1,50,000 taxable', 'retire_cap', '{"employer":"900000"}', '{"excess":"150000"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.RETIRE-CAP' AND "jurisdiction" = 'IN' AND "version" = '2020-v1' AND NOT EXISTS (SELECT 1 FROM "statutory_golden_cases" g WHERE g."rule_set_id" = "statutory_rule_sets"."id" AND g."name" = 'Employer 9,00,000: 1,50,000 taxable');
INSERT INTO "statutory_golden_cases" ("rule_set_id", "name", "fn", "input", "expected") SELECT "id", 'Employer 7,50,000 (the cap): nothing', 'retire_cap', '{"employer":"750000"}', '{"excess":"0"}' FROM "statutory_rule_sets" WHERE "statute" = 'IN.RETIRE-CAP' AND "jurisdiction" = 'IN' AND "version" = '2020-v1' AND NOT EXISTS (SELECT 1 FROM "statutory_golden_cases" g WHERE g."rule_set_id" = "statutory_rule_sets"."id" AND g."name" = 'Employer 7,50,000 (the cap): nothing');
